import {PicoRuntime} from './pico-runtime.js';
import {PICO_BOARDS} from './pico-boards.js';
import {attachMeasurementRuntime,measurementConfig} from './measurement.js';
let runtime,project,running=false,timer,serial='',circuitId=0,traceId=0,tracePins=[],traceLevels={},edges=[],traceDropped=0,measurement,listener;
const stop=()=>{running=false;clearTimeout(timer);};
function observe(cycle,inputs){for(const pin of tracePins){const high=!!inputs[pin];if(traceLevels[pin]!==high){edges.push({pin,cycle,high,...(traceLevels[pin]===undefined?{seed:true}:{})});traceLevels[pin]=high;}}if(edges.length>30000){traceDropped+=edges.length-30000;edges.splice(0,edges.length-30000);}listener?.();}
function configure(d){traceId=d.traceId??traceId;tracePins=(d.pins||tracePins).filter(p=>runtime.board.gpio.includes(Number(p.replace('GPIO',''))));traceLevels={};edges=[];traceDropped=0;runtime.circuit.onTrace=observe;observe(runtime.circuit.cycle(),runtime.inputs);measurement?.dispose();measurement=attachMeasurementRuntime({cpu:{get cycles(){return runtime.circuit.cycle();}}},{get solution(){return runtime.circuit.solution;},subscribe(fn){listener=fn;return()=>{listener=null;};}},d.measurement||measurementConfig(project),d.measurementId||0);}
function frame(type='snapshot'){const c=runtime.circuit,dc=c.snapshot(),pins=Object.fromEntries(Object.entries(c.pins).map(([p,s])=>[p,{...s,high:!!runtime.inputs[p],voltage:dc.voltages[c.solution.netlist.net(c.board.id+':'+p)]??null}])),cycles=c.cycle(),base=runtime.board.mcu==='RP2350'?0x40070000:0x40034000,ctl=runtime.rp.readUint32(base+0x30),div=runtime.rp.readUint32(base+0x24)+runtime.rp.readUint32(base+0x28)/64;postMessage({type,pico:runtime.services.snapshot(),debug:{cpuCycles:runtime.count,pc:runtime.core.PC,registers:runtime.registers(),...runtime.debugger?.snapshot(!running)},bluetooth:c.bluetooth?.snapshot(),circuitId,cycles,seconds:cycles/16000000,pins,running,serial,flashBytes:runtime.image.length,traceId,edges,traceLevels:{...traceLevels},traceDropped,measurement:measurement?.drain(),uart:{baudRate:div?runtime.hz/(16*div):0,txEnabled:!!(ctl&0x100),rxEnabled:!!(ctl&0x200)},dc:{...dc,mode:dc.mode||'synchronous-dc',externalDevices:true,...Object.fromEntries(['ledResults','deviceResults','opampResults','contactResults','sensorResults'].map(k=>[k,Object.fromEntries(c.solution[k]||[])]))},i2c:{modules:dc.devices,displays:Object.fromEntries(Object.entries(dc.devices).filter(([,d])=>d.type==='oled'))},spi:{devices:dc.devices}});serial='';edges=[];traceDropped=0;}
function tick(){if(!running)return;try{const t=performance.now();do{serial+=runtime.step(1000);if(runtime.debugger?.reason){stop();break;}}while(performance.now()-t<10);frame();if(running)timer=setTimeout(tick,0);}catch(e){stop();postMessage({type:'error',message:e.message});}}
self.onmessage=async({data:d})=>{try{switch(d.type){case'load':{stop();runtime?.dispose();if(!PICO_BOARDS[d.chip]||d.language&&d.language!=='c')throw Error('Pico worker C17 firmware gerektirir.');project=d.circuit;circuitId=d.circuitId;runtime=new PicoRuntime(Uint8Array.from(atob(d.hex),c=>c.charCodeAt(0)),d.chip);runtime.attachCircuit(project);if(d.picoNetwork)runtime.services.configureNetwork(d.picoNetwork);runtime.setDebugInfo(d.debugInfo);runtime.debugger.configure(d.breakpoints,d.watches);configure(d);frame('ready');break;}case'pico-usb':try{runtime.usbHost.command(d);}catch(e){postMessage({type:'serial-error',message:e.message});}frame();break;case'pico-ble':try{runtime.services.bleCommand(d);}catch(e){postMessage({type:'serial-error',message:e.message});}frame();break;case'pico-network':runtime.services.configureNetwork(d.config);if(project)project.settings.picoNetwork=d.config;frame();break;case'run':stop();runtime.debugger?.resume();running=true;tick();break;case'pause':stop();frame();break;case'debug-config':runtime.debugger?.configure(d.breakpoints,d.watches);frame();break;case'debug-step':stop();if(!runtime.debugger?.info)throw Error('Satır adımı için Pico C kaynağını yeniden derleyin.');runtime.debugger.beginStep();running=true;tick();break;case'step':stop();runtime.debugger?.resume();serial+=runtime.step(1);frame();break;case'reset':stop();const dbg=runtime.debugger;runtime.reset();runtime.setDebugInfo(dbg?.info);runtime.debugger.configure(dbg?.breakpoints,dbg?.watches);serial='';configure(d);frame();break;case'circuit':project=d.circuit;circuitId=d.circuitId;runtime.circuit.update(project);frame();break;case'bluetooth':{try{const scan=runtime.circuit.bluetoothCommand(d);postMessage({type:'bluetooth',bluetooth:runtime.circuit.bluetooth.snapshot(),scan});}catch(e){postMessage({type:'bluetooth-error',message:e.message});}break;}case'serial':try{runtime.queueSerial(d.text);}catch(e){postMessage({type:'serial-error',message:e.message});}break;case'probe':case'measurement':configure(d);frame();break;case'trace':break;default:throw Error('Pico worker komutu desteklenmiyor.');}}catch(e){stop();postMessage({type:'error',message:e.message});}};
